// Вход бота. Обычное сообщение — как есть. Нажатие inline-кнопки (callback_query) —
// превращаем в обычное сообщение с текстом кнопки, чтобы дальше всё шло одним путём.
const b = $('Webhook').first().json.body || {};
if (b.message) return [{ json: { message: b.message } }];
const cq = b.callback_query;
if (!cq) return [{ json: { message: b.message } }];
const m = cq.message || {};
let text = String(cq.data || '').trim();
// callback_data = opt:N; подпись берём из клавиатуры исходного сообщения (Telegram присылает её целиком)
if (/^opt:\d+$/.test(text) && m.reply_markup && Array.isArray(m.reply_markup.inline_keyboard)) {
  for (const row of m.reply_markup.inline_keyboard) for (const btn of (row || [])) {
    if (btn && btn.callback_data === text) text = String(btn.text || '').trim();
  }
}
if (/^opt:\d+$/.test(text)) text = '';
const chat = m.chat || { id: cq.from && cq.from.id, type: 'private' };
// message_id синтетический (у сообщения бота свой id, а инструменты используют его как метку источника)
const message_id = Number(String(cq.id || Date.now()).slice(-9)) || Math.floor(Date.now() / 1000);
return [{ json: {
  message: { message_id, from: cq.from, chat, date: Math.floor(Date.now() / 1000), text, via_button: true },
  callback: { id: cq.id, chat_id: chat.id, message_id: m.message_id }
} }];

const items = $input.all();
for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'voice.ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}
return items;

// Кэшируем токен бота в staticData n8n (живёт в его SQLite, не в Postgres).
// Нужен, чтобы ответить клиенту, когда Postgres недоступен и Load Config упал.
const sd = $getWorkflowStaticData('global');
sd.tokens = sd.tokens || {};
const cfg = $input.first().json;
if (cfg && cfg.bot_id && cfg.bot_token) sd.tokens[cfg.bot_id] = cfg.bot_token;
return $input.all();

// Postgres недоступен. Достаём токен из кэша, чтобы не молчать.
const sd = $getWorkflowStaticData('global');
const tokens = sd.tokens || {};
const wh = $('Webhook').first().json || {};
const botId = wh.params && wh.params.bot_id;
const chatId = wh.body && wh.body.message && wh.body.message.chat && wh.body.message.chat.id;
const token = botId ? tokens[botId] : null;
// Всегда возвращаем элемент, даже если ответить нечем: иначе ветка оборвётся
// и владелец не получит тревогу — то есть отказ станет молчаливым.
return [{ json: { bot_id: botId || null, chat_id: chatId || null, bot_token: token || null, can_reply: Boolean(token && chatId) } }];

// Клиент предупреждён — роняем выполнение, чтобы сработал Error Workflow.
// ВНИМАНИЕ: n8n отрезает в сообщении об ошибке всё до последнего «: »,
// поэтому двоеточий с пробелом внутри текста быть не должно.
const info = $('Fallback Token').first().json || {};
const sent = info.can_reply === false
  ? 'ответ клиенту НЕ отправлен (нет токена в кэше)'
  : 'ответ клиенту отправлен из кэша токенов';
const bot = info.bot_id || 'неизвестен';
throw new Error('Postgres недоступен, Load Config не отработал. ' + sent + '. Бот — ' + bot);

// Без «: » в тексте — n8n обрезает тревогу владельцу по последнему двоеточию.
const d = $('Отказ: разбор').first().json || {};
if (d.kind === 'steps') {
  throw new Error('Агент упёрся в потолок шагов, разбор не уложился. Клиент предупреждён и приглашён прислать частями. Деталь — ' + (d.raw || ''));
}
throw new Error('AI Agent не смог сформировать ответ. Вероятная причина — недоступна модель или память. Клиент предупреждён.');

// HTTP-узел «Research: саммари» отдаёт ответ Telegram и НЕ несёт бинарник.
// Возвращаем PDF и данные отчёта, взяв их у узла цикла: он выполняется
// один раз за исполнение, поэтому ссылка на него однозначна.
const src = $('Research: цикл').first();
if (!src || !src.binary || !src.binary.pdf) {
  throw new Error('PDF не найден в результате цикла — отчёт собрать не удалось');
}

// Осмысленное имя файла вместо UUID от Gotenberg.
// Telegram обрезает длинные имена (проверено: на 66 символах срезало дату),
// поэтому держимся в ~55 символах и режем заголовок по границе слова.
const d = new Date();
const p = n => String(n).padStart(2, '0');
const stamp = `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;

let title = String(src.json.topic_ru || src.json.topic || 'Разбор')
  .replace(/[\\/:*?"<>|\r\n\t]/g, ' ')   // недопустимое в именах файлов
  .replace(/\s+/g, ' ')
  .trim();

const MAX_TITLE = 38;
if (title.length > MAX_TITLE) {
  const cut = title.slice(0, MAX_TITLE);
  const sp = cut.lastIndexOf(' ');
  title = (sp > 15 ? cut.slice(0, sp) : cut);   // по границе слова, если она есть
}
title = title.replace(/[\s.,;:—-]+$/, '');
if (!title) title = 'Разбор';

const pdf = { ...src.binary.pdf, fileName: `${title} ${stamp}.pdf` };

return [{ json: src.json, binary: { pdf } }];

const msg = $('Normalize').first().json.message;
let row = {};
try { row = $('Load Profile').first().json || {}; } catch (e) { row = {}; }
const asObj = v => { if (v == null) return null; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } } return v; };
const prof = asObj(row.profile) || {};
const allergens = asObj(row.allergens) || [];
const injuries = asObj(row.injuries) || [];
const conditions = asObj(row.conditions) || [];
const medications = asObj(row.medications) || [];
const preferences = asObj(row.preferences) || [];
const exclusions = asObj(row.exclusions) || [];
const summary = (row.summary == null) ? '' : String(row.summary);
const dialogThread = (row.dialog_thread == null) ? '' : String(row.dialog_thread);
const todayFood = asObj(row.today_food) || [];
const todayWorkout = asObj(row.today_workout) || [];
const has = v => v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0);
const discList = () => { let a = prof.disciplines; if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = []; } } return Array.isArray(a) ? a : []; };
const known1 = k => { if (k === 'disciplines') return discList().length > 0; return has(prof[k]); };
const baseFields = [['sex','пол'],['birth_date','дата рождения'],['height_cm','рост'],['current_weight_kg','вес'],['timezone','часовой пояс'],['units','единицы']];
const ctxFields = [['experience_level','опыт'],['equipment','оборудование'],['days_per_week','дней в неделю'],['session_minutes','длительность тренировки'],['diet_type','тип питания']];
const goalKnown = known1('main_goal') && discList().length > 0;
const baseMissing = baseFields.filter(f => !known1(f[0])).map(f => f[1]);
const ctxMissing = ctxFields.filter(f => !known1(f[0])).map(f => f[1]);
const safetyDone = prof.onboarding_safety_done === true;
const onbDone = prof.onboarding_done === true;
const lines = [];
if (known1('main_goal')) lines.push('цель: ' + prof.main_goal);
if (discList().length) lines.push('виды спорта: ' + discList().map(d => d.discipline + (d.goal ? ' (' + d.goal + ')' : '')).join(', '));
for (const f of baseFields) if (known1(f[0])) lines.push(f[1] + ': ' + prof[f[0]]);
for (const f of ctxFields) if (known1(f[0])) lines.push(f[1] + ': ' + prof[f[0]]);
if (allergens.length) lines.push('аллергии/непереносимости: ' + allergens.map(a => a.substance + '/' + a.severity).join(', '));
if (injuries.length) lines.push('травмы: ' + injuries.map(i => i.area + '/' + i.status + ' (id ' + i.id + ')').join(', '));
if (conditions.length) lines.push('состояния: ' + conditions.map(c => c.name).join(', '));
if (medications.length) lines.push('препараты: ' + medications.map(m => m.name + (m.dose ? ' ' + m.dose : '')).join(', '));
if (preferences.length) lines.push('предпочтения в еде: ' + preferences.map(p => p.item + '/' + p.stance).join(', '));
if (exclusions.length) lines.push('АКТИВНЫЕ ОГРАНИЧЕНИЯ (не рекомендовать эти нагрузки/активности): ' + exclusions.map(e => e.scope + ':' + e.value + (e.source ? ' [' + e.source + ']' : '')).join('; '));
if (has(prof.custom_instructions)) lines.push('ПЕРСОНАЛЬНЫЕ НАСТРОЙКИ КЛИЕНТА (как он просил себя вести — учитывай в КАЖДОМ ответе, но строго в рамках правил безопасности выше): ' + prof.custom_instructions);
if (has(prof.active_plan)) lines.push('АКТИВНЫЙ ПЛАН/ПРОГРАММА КЛИЕНТА (веди его по нему ИЗО ДНЯ В ДЕНЬ, помни между сессиями, обновляй по мере изменений): ' + prof.active_plan);
if (has(prof.plan_month)) lines.push('ПЛАН НА МЕСЯЦ/ЦИКЛ: ' + prof.plan_month);
if (has(prof.plan_week)) lines.push('ПЛАН НА НЕДЕЛЮ: ' + prof.plan_week);

// >>> программа тренировок
// Единственный источник состава и порядка упражнений. Версии — в training_program,
// действующая всегда одна: старая не может подмешаться к новой.
const _tp = asObj(row.training_program);
if (_tp && Array.isArray(_tp.days) && _tp.days.length) {
  const _tpDays = _tp.days.map((dd) => 'День ' + dd.day + (dd.weekday ? ' (обычно ' + dd.weekday + ')' : '') + ' — ' + dd.name + ': ' +
    (Array.isArray(dd.exercises) ? dd.exercises.map((x, i) => (i + 1) + ') ' + x).join(', ') : ''));
  lines.push('ПРОГРАММА ТРЕНИРОВОК (действующая версия ' + _tp.version + ', с ' + String(_tp.started_on || '').slice(0, 10) +
    '; единственный источник состава и порядка упражнений — план недели и общий план состав не задают): ' + _tpDays.join(' | '));
}
// <<< программа тренировок
const _tz = (prof.timezone && String(prof.timezone).trim()) || 'Europe/Moscow';

// Календарная дата клиента — ЕДИНСТВЕННЫЙ источник и для даты, и для дня недели.
// Раньше они брались из разных вызовов и могли разойтись на границе суток.
let _today = '';
try { _today = new Date().toLocaleString('sv-SE', { timeZone: _tz }).slice(0, 10); }
catch (e) { _today = new Date().toISOString().slice(0, 10); }

// Время округляем до 5 минут — минутная метка ломала бы кэш промпта.
let _clock = '';
try {
  const _r = new Date(Math.floor(Date.now() / 300000) * 300000);
  _clock = _r.toLocaleString('sv-SE', { timeZone: _tz }).slice(11, 16);
} catch (e) { _clock = ''; }

const _DOW = ['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const _SHORT = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
const _MON = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];

// Полдень по UTC — чтобы сдвиг пояса никогда не перекинул дату на соседнюю.
const _base = Date.parse(_today + 'T12:00:00Z');
const _at = (shift) => new Date(_base + shift * 86400000);
const _dmy = (d) => String(d.getUTCDate()).padStart(2,'0') + '.' + String(d.getUTCMonth()+1).padStart(2,'0');

const _cur = _at(0);
const _dow = _cur.getUTCDay();
const _longDate = _cur.getUTCDate() + ' ' + _MON[_cur.getUTCMonth()] + ' ' + _cur.getUTCFullYear();

// Неделя целиком: боту не нужно считать, какой день каким числом.
const _mondayShift = (_dow === 0 ? -6 : 1 - _dow);
const _week = [];
for (let i = 0; i < 7; i++) {
  const d = _at(_mondayShift + i);
  const mark = (d.getUTCDay() === _dow);
  _week.push((mark ? '[' : '') + _SHORT[d.getUTCDay()] + ' ' + _dmy(d) + (mark ? ' — СЕГОДНЯ]' : ''));
}

const _todayLines = [];
// Время намеренно НЕ пишем: этот блок уходит в кэшируемый префикс, и метка времени рвала кэш каждые 5 минут. Время есть в штампе сообщения.
_todayLines.push('СЕГОДНЯ: ' + _DOW[_dow].toUpperCase() + ', ' + _longDate + ' (пояс ' + _tz + ', дата в формате ' + _today + ')');
_todayLines.push('ТЕКУЩАЯ НЕДЕЛЯ: ' + _week.join(' · '));
_todayLines.push('ДЕНЬ НЕДЕЛИ ПО СЧЁТУ: ' + (_dow === 0 ? 7 : _dow) + '-й (понедельник = 1). Если в тексте плана своя нумерация дней — сопоставляй её С ЭТИМ номером, а не с номером дня программы.');
_todayLines.push('ВЧЕРА: ' + _DOW[_at(-1).getUTCDay()] + ' ' + _dmy(_at(-1)) + '. ЗАВТРА: ' + _DOW[_at(1).getUTCDay()] + ' ' + _dmy(_at(1)) + '.');

if (has(prof.plan_started_on)) {
  try {
    const _ps = String(prof.plan_started_on).slice(0, 10);
    const _dn = Math.floor((Date.parse(_today + 'T00:00:00Z') - Date.parse(_ps + 'T00:00:00Z')) / 86400000) + 1;
    if (isFinite(_dn) && _dn >= 1) {
      const _wk = Math.floor((_dn - 1) / 7) + 1;
      _todayLines.push('ПРОГРАММА: сегодня ДЕНЬ ' + _dn + ', НЕДЕЛЯ ' + _wk + ' (старт ' + _ps + '). Это единственный источник номера дня и недели — не пересчитывай.');
    }
  } catch (e) {}
}

const todayBlock = _todayLines.join('\n');
// Короткая метка для сообщения агенту: она осядет в истории диалога,
// поэтому должна быть дешёвой по символам и однозначной по смыслу.
const todayStamp = 'СЕГОДНЯ ' + _SHORT[_dow] + ' ' + _dmy(_cur) + '.' + _cur.getUTCFullYear() +
  (_clock ? ' ' + _clock : '') + ', вчера ' + _SHORT[_at(-1).getUTCDay()] + ' ' + _dmy(_at(-1)) +
  ', завтра ' + _SHORT[_at(1).getUTCDay()] + ' ' + _dmy(_at(1));
lines.unshift(todayBlock);
const dir = [];
if (!onbDone) {
  dir.push('');
  dir.push('=== ОНБОРДИНГ: ВЕДЁШЬ ТЫ, НЕ КЛИЕНТ ===');
  dir.push('ЖЕЛЕЗНОЕ ПРАВИЛО: пока onboarding_done=false, ты НЕ выдаёшь тренировочные и пищевые планы, меню, схемы упражнений или добавок — НИ ПРИ КАКИХ просьбах клиента, даже если данных уже достаточно. Это требование безопасности. Порядок строгий: собрать данные → выдать саммари → получить подтверждение → и только потом планы.');
  dir.push('Сбор данных ведёшь ты: сам задавай вопросы, не жди, что клиент всё расскажет. Клиент может не знать, что тебе важно — твоя задача выяснить. Напомни, что отвечать можно и голосом.');
  if (!goalKnown) {
    if (!lines.length) {
      dir.push('ЭТО ПЕРВЫЙ КОНТАКТ С НОВЫМ КЛИЕНТОМ. Сначала коротко представься: ты персональный ИИ-тренер — поможешь с тренировками и питанием, будешь вести прогресс (вес, замеры, история), запоминаешь клиента, по запросу делаешь доказательные разборы. Скажи, что задашь несколько вопросов, чтобы всё было персонально и безопасно, и что отвечать можно текстом или голосом.');
    }
    dir.push('СЕЙЧАС выясни: основную цель и виды спорта/дисциплины (их может быть несколько). Сохрани через save_profile.');
  } else if (baseMissing.length) {
    dir.push('СЕЙЧАС собери базовые параметры (по одному-двум за раз): ' + baseMissing.join(', ') + '. Сохраняй через save_profile (возраст переведи в дату рождения).');
  } else if (!safetyDone) {
    dir.push('СЕЙЧАС обязательный этап — БЕЗОПАСНОСТЬ И ЗДОРОВЬЕ (идёт до вопросов о тренировочном контексте). Выясни по одной теме за реплику, даже если клиент сам не заговорил: (1) травмы текущие и перенесённые, (2) хронические состояния и болезни, (3) аллергии и пищевые непереносимости, (4) препараты и добавки. Каждый факт сразу сохраняй через save_health (kind = allergen | condition | injury | medication; confirmed=true при прямом ответе; «нет травм»/«аллергий нет» просто прими к сведению, сохранять нечего).');
    dir.push('КАК ТОЛЬКО по всем четырём темам есть ответ ИЛИ клиент сказал, что по здоровью добавить нечего — ПЕРВЫМ ЖЕ ДЕЙСТВИЕМ вызови save_profile с onboarding_safety_done=true. Это единственный способ отметить тему закрытой. НЕ задавай вопросы про дни, оборудование, опыт и питание, пока не выставил этот флаг.');
  } else if (ctxMissing.length) {
    dir.push('СЕЙЧАС уточни тренировочный и пищевой контекст: ' + ctxMissing.join(', ') + '. Сохрани через save_profile.');
  } else {
    dir.push('ВСЁ СОБРАНО, но onboarding_done ещё false. Твоя ЕДИНСТВЕННАЯ задача в этой реплике: выдай клиенту КРАТКОЕ САММАРИ всего собранного (цель, виды спорта, параметры, здоровье и ограничения, контекст тренировок и питания) и спроси, всё ли верно. НИКАКИХ планов, меню, упражнений или добавок сейчас — даже не начинай. Только после явного подтверждения клиента («да», «верно», «всё так») вызови save_profile с onboarding_done=true — и лишь в СЛЕДУЮЩЕЙ реплике сможешь строить план.');
  }
  dir.push('Если клиент прямо отказывается что-то называть — не настаивай, отметь пропуск и иди дальше; вернись к этому позже, только когда без факта нельзя дать безопасный ответ.');
} else {
  dir.push('');
  dir.push('Онбординг завершён. Новые факты профиля сохраняй через save_profile, здоровья — через save_health. Используй известное выше, не переспрашивай.');
}
let block;
if (!lines.length) block = 'Профиль клиента ПУСТ — это НОВЫЙ клиент, о нём пока ничего не известно.';
else block = 'Что уже известно о клиенте (НЕ переспрашивай это):\n- ' + lines.join('\n- ');
block += '\n' + dir.join('\n');
if (summary && summary.trim()) block = 'ВЫЖИМКА О КЛИЕНТЕ (долговременная память — опирайся на неё, это сжатая история общения):\n' + summary.trim() + '\n\n' + block;
if (dialogThread && dialogThread.trim()) block = 'НИТЬ ДИАЛОГА ПОСЛЕДНИХ ДНЕЙ (что обсуждали и о чём договорились — помни это, даже если сообщений нет в окне; журналы еды/тренировок смотри через get_progress):\n' + dialogThread.trim() + '\n\n' + block;
if (todayFood.length || todayWorkout.length) {
  const L = [];
  if (todayFood.length) {
    let tk = 0, tp = 0, tf = 0, tc = 0;
    const items = todayFood.map(x => { tk += Number(x.k) || 0; tp += Number(x.p) || 0; tf += Number(x.f) || 0; tc += Number(x.c) || 0; return (x.m ? x.m + ' — ' : '') + (x.t || '?') + ' (' + (x.k || 0) + ' ккал, Б' + (x.p || 0) + ')'; });
    L.push('Еда: ' + items.join('; ') + '. ИТОГО СЕГОДНЯ: ' + Math.round(tk) + ' ккал, Б' + Math.round(tp) + ' Ж' + Math.round(tf) + ' У' + Math.round(tc) + '.');
  }
  if (todayWorkout.length) {
    // Расход берём из базы: его посчитал код при записи, агенту считать нечего.
    let burned = 0;
    const wl = todayWorkout.map(x => {
      burned += Number(x.kc) || 0;
      const mins = Math.round((Number(x.ds) || 0) / 60);
      const parts = [];
      if (Number(x.n) > 0 && !mins) parts.push(x.n + ' подх.');
      if (mins > 0) parts.push(mins + ' мин');
      if (Number(x.kc) > 0) parts.push(Math.round(x.kc) + ' ккал');
      return (x.ex || '?') + (parts.length ? ' (' + parts.join(', ') + ')' : '');
    });
