    .replace(/^[ \t]*Calling\s+[A-Za-z_][\w.-]*\s*(?:with\s+input\s*:|["'>]).*$/gim, ' ')
    .replace(/<\/?\s*(?:antml:)?(?:invoke|parameter|function_calls|function_results)\b[^>]*>/gi, ' ')
    .replace(/\{[^{}]{0,4000}\}/g, ' ')
